import React, { Component } from 'react'
import { Card, Row, Col, Button, Skeleton } from 'antd'
import { OpenClaimStatusWrapper } from './component.style'
import querySearchBuilder from '../../../../../helpers/querySearchBuilder'
import { claimStatusForOps } from '../../../Agent/OfflineQuotes/constants'

class OpenClaimStatus extends Component {
  handleCountClick = (colour, id) => {
    const { type, filterData, startDate, endDate } = this.props
    const key = type === 'partner' ? 'partner_id' : 'owner_id'
    const data = {
      ...filterData,
      doc_received_end_date: filterData.doc_received_endDate || endDate,
      doc_received_start_date: filterData.doc_received_startDate || startDate
    }
    data.doc_received_endDate && delete data.doc_received_endDate
    data.doc_received_startDate && delete data.doc_received_startDate
    data.startDate && delete data.startDate
    data.endDate && delete data.endDate
    delete data.endDate
    data.source = 'dashboard'
    data.colour = colour
    data.status = [...claimStatusForOps]
    data[key] = id
    const queryString = querySearchBuilder(data)
    this.props.history.push(`/claims/all${queryString}`)
  }

  handleLoadMore = () => {
    const { metaData = {}, type, startDate, endDate } = this.props
    const { page_number: pageNumber } = metaData

    if (type === 'partner') {
      this.props.fetchPartnerOpenClaims({
        body: {
          page_number: pageNumber + 1,
          page_size: 10,
          ...(startDate && { start_date: startDate }),
          ...(endDate && { end_date: endDate })
        },
        seeMore: true
      })
    } else {
      this.props.fetchOperationOpenClaims({
        body: {
          page_number: pageNumber + 1,
          page_size: 10,
          ...(startDate && { start_date: startDate }),
          ...(endDate && { end_date: endDate })
        },
        seeMore: true
      })
    }
  }

  render () {
    const { heading = '', data = [], loading = false, metaData = {} } = this.props
    const { total_records: totalRecords, page_number: pageNumber, page_size: pageSize } = metaData
    const moreDataCount = totalRecords - 10 * pageNumber

    return (
      <OpenClaimStatusWrapper>
        <Card>
          <Row align='middle'>
            <Col span={15}>
              <div className='heading'>{heading}</div>
            </Col>
            <Col span={3}>
              <div className='red-legend' />
            </Col>
            <Col span={3}>
              <div className='yellow-legend' />
            </Col>
            <Col span={3}>
              <div className='green-legend' />
            </Col>
          </Row>
          <Skeleton active loading={loading} paragraph={{ rows: 9 }} title={false}>
            <div className='data-wrapper'>
              {
                data && data.map((item = {}) =>
                  <Row type='flex' justify='space-between' align='middle' key={JSON.stringify(item)}>
                    <Col span={15}>
                      <div className='name'>{item.partner || item.owner_name}</div>
                    </Col>
                    <Col span={3} className='col-margin'>
                      <div className='count' onClick={() => this.handleCountClick('RED', item.partner || item.owner_id)}>{item.RED || 0}</div>
                    </Col>
                    <Col span={3} className='col-margin'>
                      <div className='count' onClick={() => this.handleCountClick('YELLOW', item.partner || item.owner_id)}>{item.YELLOW || 0}</div>
                    </Col>
                    <Col span={3} className='col-margin'>
                      <div className='count' onClick={() => this.handleCountClick('GREEN', item.partner || item.owner_id)}>{item.GREEN || 0}</div>
                    </Col>
                  </Row>
                )
              }
            </div>
          </Skeleton>
          <Row type='flex' justify='end'>
            <Button
              className='see-more-button'
              type='primary'
              disabled={loading || ((pageNumber * pageSize) >= totalRecords)}
              onClick={this.handleLoadMore}
            >
              See more ({moreDataCount > 0 ? moreDataCount : 0})
            </Button>
          </Row>
        </Card>
      </OpenClaimStatusWrapper>
    )
  }
}

export default OpenClaimStatus
