import React, { Component } from 'react'
import { TimeCountWrapper } from './component.style'
import { Row } from 'antd'
import moment from 'moment-timezone'
import querySearchBuilder from '../../../../../helpers/querySearchBuilder'

class TimeCount extends Component {
  handleClick = type => {
    const { date } = this.props
    const dateString = moment(date).format('YYYY-MM-DD')
    const query = {}
    query.colour = type
    query.doc_received_start_date = `${dateString} 00:00:00`
    query.doc_received_end_date = `${dateString} 23:59:59`
    query.source = 'dashboard'
    const queryString = querySearchBuilder(query)
    this.props.history.push(`/claims/all${queryString}`)
  }

  render () {
    const { date = '', red = 0, yellow = 0, green = 0 } = this.props

    return (
      <TimeCountWrapper>
        <div className='date'>{moment(date).format('DD MMM')}</div>
        <Row type='flex' justify='space-around'><div className='red-legend' />
          <div className='count' onClick={() => this.handleClick('RED')}>
            {red}
          </div>
        </Row>
        <Row type='flex' justify='space-around'><div className='yellow-legend' />
          <div className='count' onClick={() => this.handleClick('YELLOW')}>
            {yellow}
          </div>
        </Row>
        <Row type='flex' justify='space-around'>
          <div className='green-legend' />
          <div className='count' onClick={() => this.handleClick('GREEN')}>
            {green}
          </div>
        </Row>
      </TimeCountWrapper>
    )
  }
}

export default TimeCount
