import React, { Component } from 'react'
import { OpenClaimCardWrapper } from './component.style'
import { Skeleton } from 'antd'
import querySearchBuilder from '../../../../../helpers/querySearchBuilder'
import { claimStatusForOps } from '../../../Agent/OfflineQuotes/constants'

class OpenClaimCard extends Component {
  getSecondaryText = () => {
    const { range } = this.props

    switch (range) {
      case 'RED':
        return 'Open More Than 7 Days'
      case 'YELLOW':
        return 'Open Between 3-7 Days'
      default:
        return 'Open Less Than 3 Days'
    }
  }

  handleClick = () => {
    const { range, filterData } = this.props
    const data = {
      ...filterData,
      doc_received_end_date: filterData.doc_received_endDate || filterData.endDate,
      doc_received_start_date: filterData.doc_received_startDate || filterData.startDate
    }
    delete data.doc_received_endDate
    delete data.doc_received_startDate
    delete data.endDate
    delete data.startDate
    data.colour = range
    data.source = 'dashboard'
    data.status = [...claimStatusForOps]
    const queryString = querySearchBuilder(data)
    this.props.history.push(`/claims/all${queryString}`)
  }

  render () {
    const { color, count = 0, loading } = this.props

    return (
      <OpenClaimCardWrapper color={color} onClick={this.handleClick}>
        <div className='primary-text'>
          <Skeleton loading={!!loading} paragraph={false} active>{count} Open Claims</Skeleton>
        </div>
        <div className='secondary-text'>{this.getSecondaryText()}</div>
      </OpenClaimCardWrapper>
    )
  }
}

export default OpenClaimCard
