import React, { Component } from 'react'
import { connect } from 'react-redux'
import _ from 'lodash'
import { Form, Row, Select, DatePicker, Button, notification } from 'antd'
import moment from 'moment-timezone'
import ClaimDashboardActions from '../../../../redux/claimsDashboard/actions'
import PolicyActions from '../../../../../redux/policy/actions'

const { Option } = Select
const { Item } = Form

const { getProducts } = PolicyActions
const {
  getAllOpenClaims,
  getPartnerOpenClaims,
  getOperationsOpenClaims
} = ClaimDashboardActions

class FilterForm extends Component {
  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const distinctValue = _.pickBy(values, _.identity)
        if (Object.keys(distinctValue).length > 0) {
          const { partners, partnerproduct_id: partnerProductId, start_date: startDate, end_date: endDate } = values
          let productKey = ''
          for (const product of this.props.products) {
            if (product.id === partnerProductId) {
              productKey = product.name
              break
            }
          }
          values.start_date = startDate && moment(startDate).format('YYYY-MM-DD 00:00:00')
          values.end_date = endDate && moment(endDate).format('YYYY-MM-DD 23:59:59')
          this.props.filterData({
            partner_id: partners,
            product_key: productKey,
            doc_received_startDate: startDate && moment(startDate).format('YYYY-MM-DD 00:00:00'),
            doc_received_endDate: endDate && moment(endDate).format('YYYY-MM-DD 23:59:59')
          })
          this.props.getAllOpenClaims({ body: { ...values } })
          this.props.getPartnerOpenClaims({ body: { ...values } })
          this.props.getOperationsOpenClaims({ body: { ...values } })
        } else {
          notification.error({ message: 'Please choose filter' })
        }
      }
    })
  }

  handleClearFilter = () => {
    this.props.filterData({})
    this.props.form.resetFields()
    this.props.getProducts()
    this.props.getAllOpenClaims()
    this.props.getPartnerOpenClaims()
    this.props.getOperationsOpenClaims()
  }

  handlePartnerSelect = partner => {
    this.props.getProducts({ query: { partner_code: partner } })
    this.props.form.resetFields('partnerproduct_id')
  }

  componentDidMount () {
    this.props.form.setFieldsValue({
      start_date: moment().subtract(7, 'days'),
      end_date: moment()
    })
  }

  render () {
    const { form, products = [], partners = [] } = this.props
    const { getFieldDecorator } = form
    const { partners: selectedPartner } = this.props.form.getFieldsValue()
    return (
      <Form onSubmit={this.handleSubmit}>
        <Row type='flex' justify='space-between' align='middle'>
          <Item label='Partner'>
            {getFieldDecorator('partners')(
              <Select
                showSearch
                placeholder='Select Partner'
                onSelect={this.handlePartnerSelect}
                dropdownMatchSelectWidth={false}
              >
                {
                  partners.map((partner, index) => <Option key={index} value={partner.code}>{partner.name}</Option>)
                }
              </Select>
            )}
          </Item>
          <Item label='Product'>
            {getFieldDecorator('partnerproduct_id')(
              <Select
                showSearch
                placeholder='Select Product'
                dropdownMatchSelectWidth={false}
                disabled={!selectedPartner}
              >
                {
                  products.map((product, index) => <Option key={`_${index}_${product.id}`} value={product.id}>{product.display_name}</Option>)
                }
              </Select>
            )}
          </Item>
          <Item label='Doc Received Start Date'>
            {getFieldDecorator('start_date', {
              rules: [{ required: form.getFieldValue('end_date'), message: 'Please select Start date' }]
            })(
              <DatePicker
                format='YYYY-MM-DD'
                placeholder='Doc Received Start Date'
                disabledDate={(current) => {
                  const customDate = moment().format('YYYY-MM-DD')
                  return current && current > moment(customDate, 'YYYY-MM-DD')
                }}
              />
            )}
          </Item>
          <Item label='Doc Received End Date'>
            {getFieldDecorator('end_date', {
              rules: [{ required: form.getFieldValue('start_date'), message: 'Please select End date' }]
            })(
              <DatePicker
                format='YYYY-MM-DD'
                placeholder='Doc Received End Date'
                disabledDate={(current) => {
                  const customDate = moment().format('YYYY-MM-DD')
                  return current && current > moment(customDate, 'YYYY-MM-DD')
                }}
              />
            )}
          </Item>
          <Item>
            <Button
              type='primary'
              htmlType='submit'
              className='form-button'
            >
              Apply Filter
            </Button>

          </Item>
          <Item>
            <Button
              type='danger'
              className='form-button'
              onClick={this.handleClearFilter}
            >
              Clear Filter
            </Button>

          </Item>
        </Row>
      </Form>
    )
  }
}

const WrapperFilterForm = Form.create()(FilterForm)

export default connect(state => ({

  irisBalance: state.ClaimDashboard.irisBalance,
  getIrisBalanceLoading: state.Loading.GET_IRIS_BALANCE,

  xenditBalance: state.ClaimDashboard.xenditBalance,
  getXenditBalanceLoading: state.Loading.GET_XENDIT_BALANCE,

  allOpenClaims: state.ClaimDashboard.allOpenClaims,

  partnerOpenClaims: state.ClaimDashboard.partnerOpenClaims,

  operationOpenClaims: state.ClaimDashboard.operationOpenClaims
}), {
  getProducts,
  getAllOpenClaims,
  getPartnerOpenClaims,
  getOperationsOpenClaims
})(WrapperFilterForm)
