import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Row, Col, Card, Icon, Spin } from 'antd'
import moment from 'moment-timezone'
import { DashboardWrapper } from './index.style'
import ClaimDashboardActions from '../../../redux/claimsDashboard/actions'
import PolicyActions from '../../../../redux/policy/actions'
import OpenClaimCard from './components/openClaimCard'
import OpenClaimStatus from './components/openClaimStatus'
import TimeCount from './components/timeCount'
import WrapperFilterForm from './components/filterForm'

const { getProducts, getPartners } = PolicyActions
const {
  getIrisBalanceAction,
  getXenditBalance,
  getAllOpenClaims,
  getPartnerOpenClaims,
  getOperationsOpenClaims,
  getDayWiseOpenClaims,
  getIrisPPIBalance,
  getIrisAusBalance
} = ClaimDashboardActions

class Dashboard extends Component {
  constructor (props) {
    super(props)
    this.state = {
      currentDate: moment().subtract(7, 'days').format('YYYY-MM-DD'),
      filterData: {},
      disableNext: true,
      startDate: moment().subtract(7, 'days').format('YYYY-MM-DD 00:00:00'),
      endDate: moment().format('YYYY-MM-DD 23:59:59')
    }
  }

  componentDidMount () {
    this.fetch()
    this.setUpInitialFilterData()
  }

  setUpInitialFilterData = () => {
    const { startDate, endDate } = this.state
    this.setState({
      filterData: {
        startDate: moment(startDate).format('YYYY-MM-DD 00:00:00'),
        endDate: moment(endDate).format('YYYY-MM-DD 23:59:59')
      }
    })
  }

  fetch = () => {
    this.props.getPartners()
    // this.props.getProducts()
    this.props.getXenditBalance()
    this.props.getIrisBalanceAction()
    this.props.getIrisPPIBalance()
    this.props.getIrisAusBalance()
    this.props.getAllOpenClaims({
      body: {
        start_date: moment().subtract(7, 'days').format('YYYY-MM-DD 00:00:00'),
        end_date: moment().format('YYYY-MM-DD 23:59:59')
      }
    }
    )
    this.props.getPartnerOpenClaims({
      body: {
        page_size: 10,
        start_date: this.state.startDate,
        end_date: this.state.endDate
      }
    })
    this.props.getOperationsOpenClaims({
      body: {
        page_size: 10,
        start_date: moment().subtract(7, 'days').format('YYYY-MM-DD 00:00:00'),
        end_date: moment().format('YYYY-MM-DD 23:59:59')
      }
    })
    this.props.getDayWiseOpenClaims({
      body: {
        start_date: moment().subtract(6, 'days').format('YYYY-MM-DD 00:00:00'),
        end_date: moment().format('YYYY-MM-DD 23:59:59')
      }
    })
  }

  // onhandlePartnerSelect = partner => {
  //   this.props.getProducts({ query: { partner_code: partner } })
  //   this.props.form.resetFields('products')
  // }

  handlePrevious = () => {
    const { currentDate } = this.state
    this.props.getDayWiseOpenClaims({
      body: {
        start_date: moment(currentDate).subtract(6, 'days').format('YYYY-MM-DD 00:00:00'),
        end_date: moment(currentDate).format('YYYY-MM-DD 23:59:59')
      }
    })
    this.setState({ currentDate: moment(currentDate).subtract(7, 'days').format('YYYY-MM-DD'), disableNext: false })
  }

  handleNext = () => {
    const { currentDate } = this.state

    if (currentDate !== moment().subtract(7, 'days').format('YYYY-MM-DD')) {
      this.props.getDayWiseOpenClaims({
        body: {
          start_date: moment(currentDate).add(8, 'days').format('YYYY-MM-DD 00:00:00'),
          end_date: moment(currentDate).add(14, 'days').format('YYYY-MM-DD 23:59:59')
        }
      })
      this.setState({
        disableNext: (moment(currentDate).add(14, 'days').format('YYYY-MM-DD') === moment().format('YYYY-MM-DD')),
        currentDate: moment(currentDate).add(8, 'days').format('YYYY-MM-DD')
      })
    } else {
      this.setState({ disableNext: false })
    }
  }

  fetchPartnerOpenClaims = payload => {
    this.props.getPartnerOpenClaims({ ...payload })
  }

  fetchOperationOpenClaims = payload => {
    this.props.getOperationsOpenClaims(payload)
  }

  onhandleFilterData = filterData => {
    this.setState({ filterData })
    // The case when filter is cleared
    if (Object.keys(filterData).length === 0) {
      this.setState({ startDate: null, endDate: null })
    }
    if (filterData.doc_received_endDate) {
      this.setState({ endDate: filterData.doc_received_endDate })
    }
    if (filterData.doc_received_startDate) {
      this.setState({ startDate: filterData.doc_received_startDate })
    }
  }

  render () {
    const {
      irisBalance = 0, irisPPIBalance = 0, xenditBalance = 0, products = [], partners = [],
      allOpenClaims = {}, partnerOpenClaims = [], partnerOpenClaimsMetaData = [],
      operationOpenClaims = [], operationOpenClaimsMetaData = [], dayWiseOpenClaims = [],
      dayWiseOpenClaimsLoading, operationOpenClaimsLoading,
      partnerOpenClaimsLoading, getIrisBalanceLoading, getIrisPPIBalanceLoading,
      getXenditBalanceLoading, allOpenClaimsLoading, history,
      irisAusBalance = 0, getIrisAusBalanceLoading
    } = this.props
    const { filterData, disableNext } = this.state

    return (
      <DashboardWrapper disableNext={disableNext}>
        <Row type='flex' justify='center'>
          <Col>
            <div className='iris-balance'>
              <Spin spinning={!!getIrisPPIBalanceLoading}>
                IRIS PPI Balance: {isNaN(irisPPIBalance) ? irisPPIBalance : irisPPIBalance.toLocaleString('en-US')}
              </Spin>
            </div>
          </Col>
          <Col>
            <div className='iris-balance'>
              <Spin spinning={!!getIrisBalanceLoading}>
                IRIS PPIB Balance:
                {isNaN(irisBalance) ? irisBalance : irisBalance.toLocaleString('en-US')}
              </Spin>
            </div>
          </Col>
          <Col>
            <div className='xendit-balance'>
              <Spin spinning={!!getXenditBalanceLoading}>
                Xendit PPIB Balance:
                {isNaN(xenditBalance) ? xenditBalance : xenditBalance.toLocaleString('en-US')}
              </Spin>
            </div>
          </Col>

          <Col>
            <div className='xendit-balance'>
              <Spin spinning={!!getIrisAusBalanceLoading}>
                Iris Aus  Balance:
                {isNaN(irisAusBalance) ? irisAusBalance : irisAusBalance.toLocaleString('en-US')}
              </Spin>
            </div>
          </Col>

        </Row>
        <Card>
          <WrapperFilterForm
            partners={partners}
            products={products}
            handlePartnerSelect={this.onhandlePartnerSelect}
            filterData={this.onhandleFilterData}
          />
          <Card>
            <div className='card-header'>ALL OPEN CLAIMS</div>
            <Row type='flex' justify='space-around'>
              <OpenClaimCard
                count={allOpenClaims.RED}
                range='RED'
                color='rgba(220,20,60,0.8)'
                history={history}
                loading={allOpenClaimsLoading}
                filterData={filterData}
              />
              <OpenClaimCard
                count={allOpenClaims.YELLOW}
                range='YELLOW'
                color='#ffff77'
                history={history}
                loading={allOpenClaimsLoading}
                filterData={filterData}
              />
              <OpenClaimCard
                count={allOpenClaims.GREEN}
                range='GREEN'
                color='rgba(152,251,152,0.8)'
                history={history}
                loading={allOpenClaimsLoading}
                filterData={filterData}
              />
            </Row>
          </Card>
          <Row type='flex' justify='space-around'>
            <OpenClaimStatus
              heading='Partner Open Claims'
              type='partner'
              history={history}
              fetchPartnerOpenClaims={this.fetchPartnerOpenClaims}
              data={partnerOpenClaims}
              metaData={partnerOpenClaimsMetaData}
              loading={partnerOpenClaimsLoading}
              filterData={filterData}
              startDate={this.state.startDate}
              endDate={this.state.endDate}
            />
            <OpenClaimStatus
              heading='Operation Open Claims'
              type='operation'
              history={history}
              fetchOperationOpenClaims={this.fetchOperationOpenClaims}
              data={operationOpenClaims}
              metaData={operationOpenClaimsMetaData}
              loading={operationOpenClaimsLoading}
              filterData={filterData}
              startDate={this.state.startDate}
              endDate={this.state.endDate}
            />
          </Row>
        </Card>
        <Card>
          <div className='card-header'>BREAKDOWN OPEN CLAIM</div>
          <Spin spinning={!!dayWiseOpenClaimsLoading}>
            <Row type='flex' justify='space-between' align='middle'>
              <Icon type='left-circle' className='arrow' onClick={this.handlePrevious} />
              {
                dayWiseOpenClaims.map((data, i) =>
                  <Col span={3} key={i}>
                    <TimeCount
                      date={data.date}
                      red={data.RED}
                      yellow={data.YELLOW}
                      green={data.GREEN}
                      history={history}
                    />
                  </Col>
                )
              }
              <Icon type='right-circle' className='arrow-right' onClick={this.handleNext} />
            </Row>
          </Spin>
        </Card>
      </DashboardWrapper>
    )
  }
}

export default connect(state => ({
  partners: state.Insurance.partners,
  products: state.Insurance.products,

  irisBalance: state.ClaimDashboard.irisBalance,
  irisPPIBalance: state.ClaimDashboard.irisPPIBalance,
  irisAusBalance: state.ClaimDashboard.irisAusBalance,
  getIrisBalanceLoading: state.Loading.GET_IRIS_BALANCE,
  getIrisPPIBalanceLoading: state.Loading.GET_IRIS_PPI_BALANCE,

  xenditBalance: state.ClaimDashboard.xenditBalance,
  getXenditBalanceLoading: state.Loading.GET_XENDIT_BALANCE,
  getIrisAusBalanceLoading: state.Loading.GET_IRIS_AUS_BALANCE,

  allOpenClaims: state.ClaimDashboard.allOpenClaims,
  allOpenClaimsLoading: state.Loading.GET_ALL_OPEN_CLAIMS,

  partnerOpenClaims: state.ClaimDashboard.partnerOpenClaims,
  partnerOpenClaimsMetaData: state.ClaimDashboard.partnerOpenClaimsMetaData,
  partnerOpenClaimsLoading: state.Loading.GET_PARTNER_OPEN_CLAIMS,

  operationOpenClaims: state.ClaimDashboard.operationOpenClaims,
  operationOpenClaimsMetaData: state.ClaimDashboard.operationOpenClaimsMetaData,
  operationOpenClaimsLoading: state.Loading.GET_OPERATION_OPEN_CLAIMS,

  dayWiseOpenClaims: state.ClaimDashboard.dayWiseOpenClaims,
  dayWiseOpenClaimsLoading: state.Loading.GET_DAY_WISE_OPEN_CLAIMS
}), {
  getIrisAusBalance,
  getIrisBalanceAction,
  getIrisPPIBalance,
  getXenditBalance,
  getProducts,
  getPartners,
  getAllOpenClaims,
  getPartnerOpenClaims,
  getOperationsOpenClaims,
  getDayWiseOpenClaims
})(Dashboard)
